#!/usr/bin/env python3
"""rnv-brand landing script, step 3 of 3: American spelling in the registers, the engine's comments, the checker and the docs

British spellings become American by Chris's ruling of 2026-10-18, from a reviewed word list. Text only: the engine's and the checker's syntax trees are unchanged apart from string text, every emitted stylesheet is byte-identical, and profile.json is not touched. Two quotations of earlier text keep their spelling.

Run it from the root of an rnv-brand checkout (a Codespace works), on the commit
named below. It writes files and commits nothing.

    python3 land_3_*.py --check     # says what it would do, writes nothing
    python3 land_3_*.py             # writes the files
    git add -A && git write-tree           # must print the result tree below
    git commit -m "<the subject above>"

BASE: the commit before it must have tree b0fec64306b9e0f5a3c1bb2c3935c7fd5e16cab1
       (step 1: rnv-brand@aaf34ed; steps 2 and 3: the commit the step before made).
RESULT: after `git add -A`, `git write-tree` prints 7a7244a0d840391aa34cb247a5697443fa0ce8f5

Every file it writes is checked three ways: the path must hold exactly the blob
it was built against (or be absent, for a new file), or already hold the result,
in which case it is left alone; anything else refuses the whole run before a
byte is written. Run it twice and the second run changes nothing.
"""
import base64, json, subprocess, sys
from pathlib import Path

STEP = "3"
BASE_TREE = "b0fec64306b9e0f5a3c1bb2c3935c7fd5e16cab1"
TARGET_TREE = "7a7244a0d840391aa34cb247a5697443fa0ce8f5"
CHANGES = json.loads(r'''[{"path": ".github/workflows/profile-drift.yml", "base": "61a828def2df18e98138ab6da89d3cfd16969491", "target": "be039c7ce927d6bf464bb0f207c6e65031d5503e", "data": ""}, {"path": "BRAND_COLORS.md", "base": "62f07e8d6be4211b5b25f1baf1755eb4747af1ce", "target": "7fbcee5ae8f7244f5ffe949aff17f47d328b83a9", "data": ""}, {"path": "BRAND_TYPE.md", "base": "841ec7a069d1c502229d2c86cc82f34e8884cdcf", "target": "fc5ce4841b3327e7d4c861932c77c5f9892bb105", "data": ""}, {"path": "README.md", "base": "658537da033a2262f9081e18f01587ba559168d5", "target": "45bdaeca3415d11f8450248ee40bc4459e369d96", "data": ""}, {"path": "engine/brand.py", "base": "51413e4e34d7030e5f7cb3ece2dfdd3a629dfa86", "target": "98a9319b0907894e8bb3d4a3bc97b8bca635b3c9", "data": ""}, {"path": "scripts/refresh_profile.py", "base": "a442ce7002d3f78c470dff4edd8bb25acacd0711", "target": "048d80f21f8a1402669446b73951f6ff7ad33f93", "data": ""}]''')

def git(*args, data=None):
    r = subprocess.run(["git", *args], input=data, capture_output=True)
    if r.returncode:
        sys.exit(f"REFUSED: git {' '.join(args)} failed: {r.stderr.decode().strip()}")
    return r.stdout.decode().strip()

def blob_of(path):
    """The blob hash git would store for this file today, filters applied; None if absent."""
    return git("hash-object", "--", path) if Path(path).is_file() else None

def main():
    check = "--check" in sys.argv
    top = git("rev-parse", "--show-toplevel")
    if Path(top).resolve() != Path.cwd().resolve():
        sys.exit(f"REFUSED: run this from the repository root, {top}")
    if not Path("engine/brand.py").is_file() or not Path("BRAND_COLORS.md").is_file():
        sys.exit("REFUSED: this is not an rnv-brand checkout")
    head_tree = git("rev-parse", "HEAD^{tree}")
    if head_tree != BASE_TREE:
        sys.exit(f"REFUSED: HEAD's tree is {head_tree[:8]}, and step {STEP} was built on {BASE_TREE[:8]}. "
                 f"Land the steps in order, each committed, on rnv-brand@aaf34ed. Nothing written.")
    todo, done, bad = [], [], []
    for c in CHANGES:
        now = blob_of(c["path"])
        if now == c["target"]:
            done.append(c["path"])
        elif now == c["base"]:
            todo.append(c)
        else:
            bad.append(f'{c["path"]}: holds {str(now)[:8]}, expected {str(c["base"])[:8]} (base) or {str(c["target"])[:8]} (result)')
    if bad:
        sys.exit("REFUSED, nothing written. These paths are in neither the state this step was built on nor its result:\n  "
                 + "\n  ".join(bad))
    print(f"step {STEP}: {len(todo)} to write, {len(done)} already applied, of {len(CHANGES)} paths")
    for c in todo:
        print(("  would write " if check else "  write ") + c["path"])
    if check:
        print("--check: nothing written."); return
    for c in todo:
        p = Path(c["path"])
        if c["target"] is None:
            p.unlink(); continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(c["data"]))
        if blob_of(c["path"]) != c["target"]:
            sys.exit(f'FAILED after writing {c["path"]}: its blob is not {c["target"][:8]}. Run `git checkout -- .` and report this.')
    others = int(git("ls-tree", "-r", "--name-only", "HEAD").count("\n")) + 1 - sum(1 for c in CHANGES if c["base"])
    print(f"every written file checked against its result blob. Left alone: the other {others} tracked files.")
    print(f"next: git add -A && git write-tree   -> must print {TARGET_TREE}")

if __name__ == "__main__":
    main()
